  "validity": true,
  "label": "1 Design anomaly",
  "reason": "High outdoor temperature typically increases cooling load, requiring higher compressor temperatures. A low setpoint during high heat suggests a design flaw or control logic error, indicating an anomaly rather than normal operation."
}

{
  "validity": true,
  "label": "2 Operational anomaly",
  "reason": "High outdoor temperature with low cooling setpoint indicates an active cooling cycle running at minimum capacity to manage heat gain, which is a typical operational response rather than a design flaw or performance degradation."
}

{
  "validity": true,
  "label": "2 Operational anomaly",
  "reason": "High fan speed combined with low outdoor dry-bulb temperature causing high indoor coil temperature indicates a control failure or sensor drift. This operational mismatch suggests improper cooling performance rather than design flaws."
}

{
  "validity": true,
  "label": "1 Design anomaly",
  "reason": "The rule indicates high fan speed correlates with low outlet air temperature and high sensor reading, suggesting a control mismatch or sensor drift where cooling intent conflicts with measured output."
}

{
  "validity": true,
  "label": "1 Design anomaly",
  "reason": "High fan speed combined with low outdoor dry-bulb temperature typically indicates a control strategy error or sensor fault causing unnecessary cooling load, rather than normal operation or performance degradation."
}

{
  "validity": true,
  "label": "2 Operational anomaly",
  "reason": "Low cooling load with high fan speed typically indicates a control mismatch or sensor fault causing unnecessary energy consumption, rather than a design flaw or performance degradation."
}

{
  "validity": true,
  "label": "2 Operational anomaly",
  "reason": "The rule indicates that when a section has low load and high fan speed, the dampers remain low. This suggests the HVAC system is failing to modulate flow based on demand, likely causing unnecessary energy consumption or poor thermal control."
}

{
  "validity": true,
  "label": "2 Operational anomaly",
  "reason": "High pressure speed with low load indicates inefficient compressor operation, likely causing unnecessary energy consumption or potential system stress during normal low-load conditions."
}
